{
  "name": "codepi",
  "displayName": "CodePi",
  "description": "Pi coding agent for VSCode",
  "version": "0.1.0",
  "publisher": "lutrarutra",
  "engines": {
    "vscode": "^1.85.0"
  },
  "categories": [
    "Chat",
    "Programming Languages"
  ],
  "main": "./dist/extension.js",
  "activationEvents": [
    "onStartupFinished",
    "onWebviewPanel:codepi-tui"
  ],
  "contributes": {
    "configuration": {
      "title": "CodePi",
      "properties": {
        "codepi.piPath": {
          "type": "string",
          "default": "",
          "description": "Path to custom pi SDK or pi binary. Leave empty to use bundled pi."
        }
      }
    },
    "viewsContainers": {
      "activitybar": [
        {
          "id": "codepi-sessions",
          "title": "PI",
          "icon": "./media/pi-icon.svg"
        }
      ]
    },
    "views": {
      "codepi-sessions": [
        {
          "id": "codepi.sessionsList",
          "name": "Sessions",
          "when": "codepi.sidebarTab == sessions"
        },
        {
          "id": "codepi.settings",
          "name": "Settings",
          "type": "webview",
          "when": "codepi.sidebarTab == settings"
        }
      ]
    },
    "icons": {
      "codepi-logo": {
        "description": "CodePi (pi) logo",
        "default": {
          "fontPath": "./media/codepi-logo.woff",
          "fontCharacter": ""
        }
      }
    },
    "colors": [
      {
        "id": "codepi.logo",
        "description": "CodePi logo color (tab handle) — white on dark themes, dark on light themes so it stays visible",
        "defaults": {
          "dark": "#ffffff",
          "light": "#1f1f1f",
          "highContrast": "#ffffff"
        }
      }
    ],
    "commands": [
      {
        "command": "codepi.openPanel",
